pper(city::varchar) as City, upper(trim(state::varchar)) as State, upper(trim(\"quick commerce city\"::varchar)) as qc_city_name, row_number() over (partition by upper(trim(\"quick commerce city\"::varchar)) order by 1) as rw FROM public.anveshan_qc_location_mapping ) where rw = 1 ) lm ON lower(lm.qc_city_name) = lower(cast(bb.source_city_name as varchar)) ) b LEFT JOIN ( SELECT * FROM ( SELECT master_sku as commonsku, bigbasket_sku as marketplace_sku, parent_category as category, tax_rate, product_name, parent_mrp, cogs, ROW_NUMBER() OVER (PARTITION BY bigbasket_sku ORDER BY LENGTH(COALESCE(bigbasket_sku, \'\')) DESC) rw FROM public.anveshan_sku_master ) WHERE rw = 1 ) p ON LOWER(REPLACE(REPLACE(b.product_id::varchar, \' \', \'\'),\'\"\',\'\')) = LOWER(p.marketplace_sku) where b.rw = 1 ) ;",
